result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/loader.py", "content": "#!/usr/bin/env python3
"""File-arrival ledger loader.

Scans a landing/ directory for CSV files and loads only files whose
(filename, sha256) pair has never been seen before.  Rows are appended to a
target table that carries a ``source_file`` column.

Replace semantics: if a file re-arrives with the same filename but a new
sha256 (a modified re-ship), the loader first deletes that file's previous
rows from the target table, then loads the new content.

Failure semantics: a malformed CSV (e.g. bad column count) records a FAILED
row in the ledger and leaves the target table untouched for that file.
"""
from __future__ import annotations

import csv
import hashlib
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

SCHEMA = """
CREATE TABLE IF NOT EXISTS ledger (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    filename  TEXT    NOT NULL,
    sha256    TEXT    NOT NULL,
    status    TEXT    NOT NULL CHECK (status IN ('OK', 'FAILED')),
    loaded_at TEXT    NOT NULL,
    row_count INTEGER,
    UNIQUE (filename, sha256)
);

CREATE TABLE IF NOT EXISTS target (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    source_file TEXT NOT NULL,
    col1 TEXT,
    col2 TEXT,
    col3 TEXT
);
"""

EXPECTED_COLUMNS = 3  # data columns per CSV row (header excluded)


@dataclass(frozen=True)
class LoadResult:
    filename: str
    sha256: str
    status: str        # "LOADED", "SKIPPED", "FAILED"
    rows_loaded: int = 0


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def sha256_of(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


class LedgerLoader:
    def __init__(self, db_path: str | Path):
        self.db_path = str(db_path)
        with self._connect() as conn:
            conn.executescript(SCHEMA)

    def _connect(self) -> sqlite3.Connection:
        conn = sqlite3.connect(self.db_path)
        conn.execute("PRAGMA foreign_keys = ON")
        return conn

    # -- ledger helpers ----------------------------------------------------

    def seen_sha256s(self, conn: sqlite3.Connection, filename: str) -> set[str]:
        rows = conn.execute(
            "SELECT sha256 FROM ledger WHERE filename = ?", (filename,)
        ).fetchall()
        return {r[0] for r in rows}

    def ledger_entries(self) -> list[tuple]:
        with self._connect() as conn:
            return conn.execute(
                "SELECT filename, sha256, status, loaded_at, row_count "
                "FROM ledger ORDER BY id"
            ).fetchall()

    # -- loading -----------------------------------------------------------

    def load_directory(self, landing: Path) -> list[LoadResult]:
        results: list[LoadResult] = []
        for path in sorted(p for p in landing.iterdir() if p.is_file() and p.suffix == ".csv"):
            results.append(self.load_file(path))
        return results

    def load_file(self, path: Path) -> LoadResult:
        filename = path.name
        digest = sha256_of(path)
        conn = self._connect()
        try:
            if digest in self.seen_sha256s(conn, filename):
                return LoadResult(filename, digest, "SKIPPED")

            try:
                rows = self._parse_csv(path)
            except ValueError as exc:
                conn.execute(
                    "INSERT OR REPLACE INTO ledger "
                    "(filename, sha256, status, loaded_at, row_count) "
                    "VALUES (?, ?, 'FAILED', ?, NULL)",
                    (filename, digest, utc_now_iso()),
                )
                conn.commit()
                return LoadResult(filename, digest, "FAILED")

            # Replace semantics: drop this filename's previous rows before
            # appending the new shipment.
            conn.execute("DELETE FROM target WHERE source_file = ?", (filename,))
            conn.executemany(
                "INSERT INTO target (source_file, col1, col2, col3) "
                "VALUES (?, ?, ?, ?)",
                [(filename,) + tuple(r) for r in rows],
            )
            conn.execute(
                "INSERT INTO ledger "
                "(filename, sha256, status, loaded_at, row_count) "
                "VALUES (?, ?, 'OK', ?, ?)",
                (filename, digest, utc_now_iso(), len(rows)),
            )
            conn.commit()
            return LoadResult(filename, digest, "LOADED", len(rows))
        finally:
            conn.close()

    @staticmethod
    def _parse_csv(path: Path) -> list[list[str]]:
        """Parse a CSV file; raise ValueError on inconsistent column counts."""
        with path.open(newline="", encoding="utf-8") as fh:
            reader = csv.reader(fh)
            rows = [row for row in reader if row]
        if not rows:
            raise ValueError("empty CSV")
        header_len = len(rows[0])
        for i, row in enumerate(rows[1:], start=1):
            if len(row) != header_len:
                raise ValueError(
                    f"bad column count on line {i + 1}: expected {header_len}, got {len(row)}"
                )
            if len(row) != EXPECTED_COLUMNS:
                raise ValueError(
                    f"line {i + 1}: expected {EXPECTED_COLUMNS} columns, got {len(row)}"
                )
        return rows[1:]  # skip header


def main() -> None:
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("landing", type=Path)
    parser.add_argument("--db", default="ledger.db")
    args = parser.parse_args()
    loader = LedgerLoader(args.db)
    for res in loader.load_directory(args.landing):
        print(f"{res.filename}: {res.status} ({res.rows_loaded} rows)")


if __name__ == "__main__":
    main()
"})
